[
  {
    "text": "WorldLines presents the translation of long-term memory into embodied plans as a mechanism to address partial observability and overwritten world states, not as a separate problem definition.",
    "topic": "Framing of memory-to-plan translation"
  },
  {
    "text": "Partial observability and overwritten world states are defined in WorldLines as properties of the environment that exist regardless of the agent's architecture.",
    "topic": "Environmental properties"
  },
  {
    "text": "The memory-to-plan translation is one architectural choice among many possible solutions to environmental challenges, not an inevitable design.",
    "topic": "Architectural design space"
  },
  {
    "text": "Classifying the translation as a subproblem of partial observability does not conflict with it being a design choice; it situates the translation as a response to environmental constraints.",
    "topic": "Design choice vs. subproblem relationship"
  }
]
